mapper.select:
SELECT COUNT(*) FROM ( SELECT c.c_session FROM chatbot c LEFT JOIN user u ON c.u_idx = u.u_idx
GROUP BY c.c_session, u.u_idx
) AS session_count

SELECT c.c_session AS chat_session, u.u_idx AS user_idx, u.u_name AS user_name, u.u_email AS user_email, u.u_role AS user_role, DATE_FORMAT(u.u_created, '%Y-%m-%d') AS user_created, /* 세션 최초 메시지 (c_idx 오름차순 첫 번째) */ (SELECT c2.c_message FROM chatbot c2 WHERE c2.c_session = c.c_session ORDER BY c2.c_idx ASC LIMIT 1) AS first_message, COUNT(c.c_idx) AS msg_count, DATE_FORMAT(MIN(c.c_time), '%Y-%m-%d') AS start_time, DATE_FORMAT(MAX(c.c_time), '%Y-%m-%d') AS end_time, /* 미해결 메시지 수 (c_response 가 비어 있는 건) */ SUM(CASE WHEN (c.c_response IS NULL OR c.c_response = '') THEN 1 ELSE 0 END) AS unresolved_count FROM chatbot c LEFT JOIN user u ON c.u_idx = u.u_idx
GROUP BY c.c_session, u.u_idx, u.u_name, u.u_email, u.u_role, u.u_created
ORDER BY start_time DESC LIMIT #{numPerPage} OFFSET #{offset}
